<script setup lang="ts">
import {ref,onMounted} from 'vue';import {adminApi} from '@/api';import type {Booking,Lesson,Equipment,User,BookingStatus} from '@/types';
const tab=ref('bookings'),bookings=ref<Booking[]>([]),lessons=ref<Lesson[]>([]),equipment=ref<Equipment[]>([]),users=ref<User[]>([]),error=ref(''),loading=ref(true);
async function load(){loading.value=true;error.value='';try{const [b,l,e,u]=await Promise.all([adminApi.bookings(),adminApi.lessons(),adminApi.equipment(),adminApi.users()]);bookings.value=b;lessons.value=l;equipment.value=e;users.value=u}catch(e){error.value='Не удалось загрузить'}finally{loading.value=false}}
async function status(id:number,value:BookingStatus){try{await adminApi.setBookingStatus(id,value);await load()}catch(e){error.value='Не удалось загрузить'}}
async function removeLesson(id:number){if(!confirm('Удалить услугу?'))return;try{await adminApi.deleteLesson(id);await load()}catch(e){error.value='Не удалось загрузить'}}
async function removeEquipment(id:number){if(!confirm('Удалить оборудование?'))return;try{await adminApi.deleteEquipment(id);await load()}catch(e){error.value='Не удалось загрузить'}}
onMounted(load);
</script><template><div class="container section section--top"><h1 class="h1">Администрирование</h1><p class="lead">Управление основными данными курорта</p><div class="filters"><button v-for="t in [['bookings','Бронирования'],['lessons','Услуги'],['equipment','Оборудование'],['users','Пользователи']]" :key="t[0]" class="filter-pill" :class="{'filter-pill--active':tab===t[0]}" @click="tab=t[0]">{{t[1]}}</button></div><div class="card panel"><p v-if="loading">Загрузка...</p><p v-else-if="error" class="state-error">{{error}}</p><div v-else class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Название / имя</th><th>Информация</th><th>Действие</th></tr></thead><tbody v-if="tab==='bookings'"><tr v-for="b in bookings" :key="b.id"><td>{{b.id}}</td><td>{{b.title}}</td><td>{{b.clientName}} · {{b.status}}</td><td><select class="field" :value="b.status" @change="status(b.id,($event.target as HTMLSelectElement).value as BookingStatus)"><option value="pending">Ожидает</option><option value="paid">Оплачено</option><option value="completed">Завершено</option><option value="cancelled">Отменено</option></select></td></tr></tbody><tbody v-if="tab==='lessons'"><tr v-for="l in lessons" :key="l.id"><td>{{l.id}}</td><td>{{l.title}}</td><td>{{l.price}} ₽</td><td><button class="btn btn--danger btn--sm" @click="removeLesson(l.id)">Удалить</button></td></tr></tbody><tbody v-if="tab==='equipment'"><tr v-for="e in equipment" :key="e.id"><td>{{e.id}}</td><td>{{e.title}}</td><td>{{e.pricePerHour}} ₽/ч</td><td><button class="btn btn--danger btn--sm" @click="removeEquipment(e.id)">Удалить</button></td></tr></tbody><tbody v-if="tab==='users'"><tr v-for="u in users" :key="u.id"><td>{{u.id}}</td><td>{{u.name}}</td><td>{{u.email}}</td><td>{{u.role}}</td></tr></tbody></table></div></div><p class="muted small">Создание и редактирование сущностей подключается через API. Серверные права доступа проверяет backend.</p></div></template>
